29	template <typename T>
30	__aicore__ inline void LoadGmToUb(
31	    AscendC::LocalTensor<T> &dst,
32	    AscendC::GlobalTensor<T> src,
33	    uint32_t count)
34	{
35	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
36	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
37	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
38	}
39	
40	template <typename T>
41	__aicore__ inline void StoreUbToGm(
42	    AscendC::GlobalTensor<T> dst,
43	    AscendC::LocalTensor<T> &src,
44	    uint32_t count)
45	{
46	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
47	    AscendC::DataCopyPad(dst, src, copyParams);
48	}
