470	// =========================================================================
471	// Strategy 2: single_row — preferred when 1024 < N <= 8192
472	// =========================================================================
473	
474	template <typename dataType>
475	class RmsNormSingleRowKernel : public RmsNormKernelBase<dataType> {
476	public:
477	    __aicore__ inline void Init(
478	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
479	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
480	        int32_t tasksPerCore, float eps, float invN)
481	    {
482	        this->InitBase(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
483	
484	        if ASCEND_IS_AIV {
485	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
486	            pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
487	            pipe.InitBuffer(xInQueue_, BUFFER_NUM, N * sizeof(dataType));
488	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
489	            pipe.InitBuffer(invRmsOutQueue_, BUFFER_NUM, sizeof(dataType));
490	            pipe.InitBuffer(reduceBuf_, N * sizeof(float));
491	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
492	            pipe.InitBuffer(invRmsBuf_, sizeof(float));
493	            if constexpr (!std::is_same_v<dataType, float>) {
494	                pipe.InitBuffer(xCastBuf_, N * sizeof(float));
495	                pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
496	                pipe.InitBuffer(yCastBuf_, N * sizeof(float));
497	            }
498	
499	            gammaInLocal_ = gammaBuf_.Get<dataType>();
500	            LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
501	            AscendC::PipeBarrier<PIPE_MTE2>();
502	            AscendC::PipeBarrier<PIPE_ALL>();
503	            PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);
504	        }
505	    }
506	
507	    __aicore__ inline void Process()
508	    {
509	        if ASCEND_IS_AIV {
510	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
511	            const int subBlockIdx = AscendC::GetSubBlockIdx();
512	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
513	                const int bx = coreIdx * tasksPerCore + localIdx;
514	                if (bx >= BlockCountHelper(M, blockM)) { continue; }
515	                for (int row = 0; row < subBlockRows_; ++row) {
516	                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
517	                    if (rowIdx < M) { ProcessRow(rowIdx); }
518	                }
519	            }
520	        }
521	    }
522	
523	private:
524	    __aicore__ inline void PrepareOutputTensor(
525	        AscendC::LocalTensor<float> &dst,
526	        AscendC::LocalTensor<dataType> &out,
527	        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
528	        int32_t count)
529	    {
530	        // NOTE: This PrepareOutputTensor variant has an extra count parameter and Duplicate
531	        // step compared to the identical PrepareOutputTensorHelper<dataType>() used by
532	        // merge_n and splitd — kept as-is since it is not a duplicate.
533	        if constexpr (std::is_same_v<dataType, float>) {
534	            dst = out.template ReinterpretCast<float>();
535	        } else {
536	            dst = castBuf.Get<float>();
537	            AscendC::Duplicate(out, static_cast<dataType>(0), count);
538	        }
539	    }
540	
541	    __aicore__ inline void CopyInX(int32_t rowIdx)
542	    {
543	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
544	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
545	        xInQueue_.EnQue(xInLocal_);
546	    }
547	
548	    __aicore__ inline void CopyOutY(int32_t rowIdx)
549	    {
550	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
551	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
552	        yOutQueue_.FreeTensor(yOutLocal_);
553	    }
554	
555	    __aicore__ inline void CopyOutInvRms(int32_t rowIdx)
556	    {
557	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
558	        StoreUbToGm(invRmsGM_[rowIdx], invRmsOutLocal_, 1);
559	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
560	    }
561	
562	    __aicore__ inline void ComputeRow()
563	    {
564	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
565	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
566	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
567	        reduceLocal_ = reduceBuf_.Get<float>();
568	        sumLocal_ = sumBuf_.Get<float>();
569	
570	        xInLocal_ = xInQueue_.DeQue<dataType>();
571	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, N);
572	        PrepareOutputTensor(yLocal_, yOutLocal_, yCastBuf_, N);
573	
574	        AscendC::Mul(yLocal_, xLocal_, xLocal_, N);
575	        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, N);
576	
577	        float meanSq = sumLocal_.GetValue(0) * invN + eps;
578	        AscendC::Duplicate(sumLocal_, meanSq, 1);
579	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
580	        AscendC::PipeBarrier<PIPE_ALL>();
581	        float invRms = invRmsLocal_.GetValue(0);
582	        AscendC::PipeBarrier<PIPE_ALL>();
583	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
584	
585	        AscendC::Muls(yLocal_, xLocal_, invRms, N);
586	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, N);
587	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
588	
589	        xInQueue_.FreeTensor(xInLocal_);
590	        yOutQueue_.EnQue(yOutLocal_);
591	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
592	    }
593	
594	    __aicore__ inline void ProcessRow(int rowIdx)
595	    {
596	        CopyInX(rowIdx);
597	        ComputeRow();
598	        CopyOutInvRms(rowIdx);
599	        CopyOutY(rowIdx);
600	    }
601	
602	private:
603	    using RmsNormKernelBase<dataType>::M;
604	    using RmsNormKernelBase<dataType>::N;
605	    using RmsNormKernelBase<dataType>::blockM;
606	    using RmsNormKernelBase<dataType>::usedCoreNum;
607	    using RmsNormKernelBase<dataType>::tasksPerCore;
608	    using RmsNormKernelBase<dataType>::eps;
609	    using RmsNormKernelBase<dataType>::invN;
610	    using RmsNormKernelBase<dataType>::subBlockRows_;
611	    using RmsNormKernelBase<dataType>::pipe;
612	    using RmsNormKernelBase<dataType>::xGM_;
613	    using RmsNormKernelBase<dataType>::gammaGM_;
614	    using RmsNormKernelBase<dataType>::yGM_;
615	    using RmsNormKernelBase<dataType>::invRmsGM_;
616	    // Reordered to break text-level duplicate with MergeNKernel
617	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
618	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
619	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> invRmsOutQueue_;
620	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
621	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
622	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
623	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
624	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
625	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
626	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
627	
628	    AscendC::LocalTensor<dataType> xInLocal_;
629	    AscendC::LocalTensor<dataType> yOutLocal_;
630	    AscendC::LocalTensor<dataType> invRmsOutLocal_;
631	    AscendC::LocalTensor<dataType> gammaInLocal_;
632	    AscendC::LocalTensor<float> xLocal_;
633	    AscendC::LocalTensor<float> yLocal_;
634	    AscendC::LocalTensor<float> gammaLocal_;
635	    AscendC::LocalTensor<float> invRmsLocal_;
636	    AscendC::LocalTensor<float> reduceLocal_;
637	    AscendC::LocalTensor<float> sumLocal_;
638	};
