640	// =========================================================================
641	// Strategy 3: splitd — preferred when N > 8192
642	// =========================================================================
643	
644	template <typename dataType>
645	class RmsNormSplitDKernel : public RmsNormKernelBase<dataType> {
646	public:
647	    __aicore__ inline void Init(
648	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
649	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
650	        int32_t tasksPerCore, float eps, float invN)
651	    {
652	        this->InitBase(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
653	
654	        if ASCEND_IS_AIV {
655	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
656	            pipe.InitBuffer(xInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
657	            pipe.InitBuffer(gammaInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
658	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
659	            pipe.InitBuffer(invRmsOutQueue_, BUFFER_NUM, sizeof(dataType));
660	            pipe.InitBuffer(reduceBuf_, kBlockN * sizeof(float));
661	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
662	            pipe.InitBuffer(tempBuf_, kTileFloatBytes);
663	            pipe.InitBuffer(invRmsBuf_, sizeof(float));
664	            if constexpr (!std::is_same_v<dataType, float>) {
665	                pipe.InitBuffer(xCastBuf_, kTileFloatBytes);
666	                pipe.InitBuffer(gammaCastBuf_, kTileFloatBytes);
667	                pipe.InitBuffer(yCastBuf_, kTileFloatBytes);
668	            }
669	        }
670	    }
671	
672	    __aicore__ inline void Process()
673	    {
674	        if ASCEND_IS_AIV {
675	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
676	            const int subBlockIdx = AscendC::GetSubBlockIdx();
677	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
678	                const int bx = coreIdx * tasksPerCore + localIdx;
679	                if (bx >= BlockCountHelper(M, blockM)) { continue; }
680	                for (int row = 0; row < subBlockRows_; ++row) {
681	                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
682	                    if (rowIdx < M) { ProcessRow(rowIdx); }
683	                }
684	            }
685	        }
686	    }
687	
688	private:
689	    static constexpr int kBlockN = 1024;
690	    static constexpr uint32_t kTileFloatBytes = kBlockN * sizeof(float);
691	
692	    __aicore__ inline int32_t NumTiles() const
693	    {
694	        return (N + kBlockN - 1) / kBlockN;
695	    }
696	
697	    __aicore__ inline int32_t GetValidN(int32_t colBase) const
698	    {
699	        return (colBase + kBlockN <= N) ? kBlockN : (N - colBase);
700	    }
701	
702	    __aicore__ inline void CopyInX(int32_t rowIdx, int32_t colBase, int32_t validN)
703	    {
704	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
705	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
706	        xInQueue_.EnQue(xInLocal_);
707	    }
708	
709	    __aicore__ inline void CopyInGamma(int32_t colBase, int32_t validN)
710	    {
711	        gammaInLocal_ = gammaInQueue_.AllocTensor<dataType>();
712	        LoadGmToUb(gammaInLocal_, gammaGM_[colBase], static_cast<uint32_t>(validN));
713	        gammaInQueue_.EnQue(gammaInLocal_);
714	    }
715	
716	    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
717	    {
718	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
719	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase], yOutLocal_, static_cast<uint32_t>(validN));
720	        yOutQueue_.FreeTensor(yOutLocal_);
721	    }
722	
723	    __aicore__ inline void CopyOutInvRms(int32_t rowIdx)
724	    {
725	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
726	        StoreUbToGm(invRmsGM_[rowIdx], invRmsOutLocal_, 1);
727	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
728	    }
729	
730	    __aicore__ inline float ComputeInvRms(int32_t rowIdx)
731	    {
732	        reduceLocal_ = reduceBuf_.Get<float>();
733	        sumLocal_ = sumBuf_.Get<float>();
734	        tempLocal_ = tempBuf_.Get<float>();
735	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
736	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
737	        float sumSq = 0.0f;
738	
739	        for (int by = 0; by < NumTiles(); ++by) {
740	            const int colBase = by * kBlockN;
741	            const int validN = GetValidN(colBase);
742	
743	            CopyInX(rowIdx, colBase, validN);
744	
745	            xInLocal_ = xInQueue_.DeQue<dataType>();
746	            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
747	            AscendC::Mul(tempLocal_, xLocal_, xLocal_, validN);
748	            AscendC::ReduceSum<float>(sumLocal_, tempLocal_, reduceLocal_, validN);
749	            sumSq += sumLocal_.GetValue(0);
750	            xInQueue_.FreeTensor(xInLocal_);
751	        }
752	
753	        AscendC::Duplicate(sumLocal_, sumSq * invN + eps, 1);
754	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
755	        AscendC::PipeBarrier<PIPE_ALL>();
756	        float invRms = invRmsLocal_.GetValue(0);
757	        AscendC::PipeBarrier<PIPE_ALL>();
758	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
759	
760	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
761	        return invRms;
762	    }
763	
764	    __aicore__ inline void ComputeTile(float invRms, int32_t validN)
765	    {
766	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
767	        xInLocal_ = xInQueue_.DeQue<dataType>();
768	        gammaInLocal_ = gammaInQueue_.DeQue<dataType>();
769	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
770	        PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, validN);
771	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
772	        AscendC::Muls(yLocal_, xLocal_, invRms, validN);
773	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, validN);
774	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, validN);
775	        xInQueue_.FreeTensor(xInLocal_);
776	        gammaInQueue_.FreeTensor(gammaInLocal_);
777	        yOutQueue_.EnQue(yOutLocal_);
778	    }
779	
780	    __aicore__ inline void ProcessRow(int rowIdx)
781	    {
782	        float invRms = ComputeInvRms(rowIdx);
783	        CopyOutInvRms(rowIdx);
784	
785	        for (int by = 0; by < NumTiles(); ++by) {
786	            const int colBase = by * kBlockN;
787	            const int validN = GetValidN(colBase);
788	
789	            CopyInX(rowIdx, colBase, validN);
790	            CopyInGamma(colBase, validN);
791	            ComputeTile(invRms, validN);
792	            CopyOutY(rowIdx, colBase, validN);
793	        }
794	    }
795	
796	private:
797	    using RmsNormKernelBase<dataType>::M;
798	    using RmsNormKernelBase<dataType>::N;
799	    using RmsNormKernelBase<dataType>::blockM;
800	    using RmsNormKernelBase<dataType>::usedCoreNum;
801	    using RmsNormKernelBase<dataType>::tasksPerCore;
802	    using RmsNormKernelBase<dataType>::eps;
803	    using RmsNormKernelBase<dataType>::invN;
804	    using RmsNormKernelBase<dataType>::subBlockRows_;
805	    using RmsNormKernelBase<dataType>::pipe;
806	    using RmsNormKernelBase<dataType>::xGM_;
807	    using RmsNormKernelBase<dataType>::gammaGM_;
808	    using RmsNormKernelBase<dataType>::yGM_;
809	    using RmsNormKernelBase<dataType>::invRmsGM_;
810	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
811	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> gammaInQueue_;
812	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
813	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> invRmsOutQueue_;
814	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
815	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
816	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf_;
817	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
818	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
819	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
820	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
821	
822	    AscendC::LocalTensor<dataType> xInLocal_;
823	    AscendC::LocalTensor<dataType> gammaInLocal_;
824	    AscendC::LocalTensor<dataType> yOutLocal_;
825	    AscendC::LocalTensor<dataType> invRmsOutLocal_;
826	    AscendC::LocalTensor<float> invRmsLocal_;
827	    AscendC::LocalTensor<float> xLocal_;
828	    AscendC::LocalTensor<float> gammaLocal_;
829	    AscendC::LocalTensor<float> yLocal_;
830	    AscendC::LocalTensor<float> reduceLocal_;
831	    AscendC::LocalTensor<float> sumLocal_;
