835	// =========================================================================
836	// Shared dtype-dispatch helper — eliminates the duplicated if/else-if/else chains
837	// in the three kernel entry points below.
838	// =========================================================================
839	
840	template <template <typename> class Kernel, typename... ExtraArgs>
841	__aicore__ inline void DispatchRmsNorm(
842	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
843	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
844	    int32_t tasksPerCore, float eps, float invN,
845	    int64_t dtypeFlag, ExtraArgs... extraArgs)
846	{
847	    if (dtypeFlag == 0) {
848	        Kernel<float> kernel;
849	        kernel.Init(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
850	        kernel.Process();
851	    } else if (dtypeFlag == 1) {
852	        Kernel<half> kernel;
853	        kernel.Init(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
854	        kernel.Process();
855	    } else {
856	        Kernel<bfloat16_t> kernel;
857	        kernel.Init(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
858	        kernel.Process();
859	    }
860	}
861	
862	// =========================================================================
863	// Kernel entry points — Abs-style: single __global__ per strategy with dtype dispatch
864	// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
865	// =========================================================================
866	
867	extern "C" __global__ __aicore__ void rms_norm_merge_n(
868	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
869	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
