// AscendC DequantSwigluQuant kernel — fused dequant(int32→fp32) + SwiGLU + per-row int8 quant
// Single strategy: per-row tile-by-tile processing along H dimension.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_H = 512;           // output elements per tile
constexpr int32_t TILE_IN = 2 * TILE_H;   // input elements per tile (2*H for interleaved)

// ===========================================================================
// Inline helpers
// ===========================================================================

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

__aicore__ inline int32_t CeilDiv(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUbPad(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGmPad(
    AscendC::GlobalTensor<T> &dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// ===========================================================================
// Kernel class
// ===========================================================================

class DequantSwigluQuantKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR weightScale, GM_ADDR activationScale,
        GM_ADDR quantScale, GM_ADDR y, GM_ADDR rowScale,
        int32_t M, int32_t N, int32_t H,
        int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
        int64_t swigluMode, int64_t activateLeft,
        float clampLimit, float gluAlpha, float gluBeta)
    {
        this->M_ = M;
        this->N_ = N;
        this->H_ = H;
        this->blockM_ = blockM;
        this->usedCoreNum_ = usedCoreNum;
        this->tasksPerCore_ = tasksPerCore;
        this->swigluMode_ = static_cast<int32_t>(swigluMode);
        this->activateLeft_ = static_cast<int32_t>(activateLeft);
        this->clampLimit_ = clampLimit;
        this->gluAlpha_ = gluAlpha;
        this->gluBeta_ = gluBeta;
        this->inv127_ = 1.0f / 127.0f;
        this->vecNum_ = AscendC::GetSubBlockNum();

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(x),
                             static_cast<uint64_t>(M) * N);
        wsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(weightScale),
                              static_cast<uint64_t>(1) * N);
        asGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(activationScale),
                              static_cast<uint64_t>(M) * 1);
        qsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(quantScale),
                              static_cast<uint64_t>(1) * H);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y),
                             static_cast<uint64_t>(M) * H);
        rsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(rowScale),
                              static_cast<uint64_t>(M));

        if ASCEND_IS_AIV {
            InitBuffers();
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx() / vecNum_;
            int32_t subBlockIdx = AscendC::GetSubBlockIdx();
            int32_t subBlockRows = blockM_ / vecNum_;
            int32_t mNum = CeilDiv(M_, blockM_);

            for (int32_t localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                int32_t bx = coreIdx * tasksPerCore_ + localIdx;
                if (bx >= mNum) { continue; }

                for (int32_t row = 0; row < subBlockRows; ++row) {
                    int32_t rowIdx = bx * blockM_ + subBlockIdx * subBlockRows + row;
                    if (rowIdx >= M_) { continue; }
                    ProcessRow(rowIdx);
                }
            }
        }
    }

private:
    // -----------------------------------------------------------------------
    // Buffer initialization
    // -----------------------------------------------------------------------
    __aicore__ inline void InitBuffers()
    {
        // Smooth quant accumulation buffer: holds fp32 output for entire row
        pipe_.InitBuffer(smoothBuf_, H_ * sizeof(float));
        // Reduce temp buffer for absmax
        pipe_.InitBuffer(reduceTmp_, 2 * TILE_H * sizeof(float));
        // Absmax scalar buffer
        pipe_.InitBuffer(absmaxBuf_, sizeof(float));
        // Quantize temp buffer
        pipe_.InitBuffer(quantTmp_, TILE_H * sizeof(float));
        // Input queue
        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, TILE_IN * sizeof(int32_t));
        // Weight scale tile loading queue
        pipe_.InitBuffer(wsInQueue_, BUFFER_NUM, TILE_IN * sizeof(float));
        // Quant scale tile loading
        pipe_.InitBuffer(qsBuf_, TILE_H * sizeof(float));
        // Dequant buffers (fp32)
        pipe_.InitBuffer(deqBuf_, TILE_IN * sizeof(float));
        // SwiGLU intermediate buffers
        pipe_.InitBuffer(swBuf_, TILE_H * sizeof(float));
        pipe_.InitBuffer(sigBuf_, TILE_H * sizeof(float));
        pipe_.InitBuffer(tmpBuf_, TILE_H * sizeof(float));
    }

    // -----------------------------------------------------------------------
    // Per-row processing
    // -----------------------------------------------------------------------
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        float asVal = asGM_.GetValue(rowIdx);
        float absmax = 0.0f;

        // === Pass 1: compute smooth quant + track absmax ===
        ComputeSmoothQuantPass(rowIdx, asVal, absmax);

        // === Compute scale ===
        float scale = absmax * inv127_;
        float safeScale = (scale > 0.0f) ? scale : 1.0f;

        // Write row_scale
        rsGM_.SetValue(rowIdx, safeScale);

        // === Pass 2: quantize and write int8 output ===
        QuantizePass(rowIdx, safeScale);
    }

    __aicore__ inline void ComputeSmoothQuantPass(int32_t rowIdx, float asVal, float &absmax)
    {
        int32_t hTiles = CeilDiv(H_, TILE_H);

        for (int32_t ht = 0; ht < hTiles; ++ht) {
            int32_t outStart = ht * TILE_H;
            int32_t curOut = (outStart + TILE_H <= H_) ? TILE_H : (H_ - outStart);
            int32_t curIn = curOut * 2;  // 2x input elements

            if (swigluMode_ == 0) {
                ProcessMode0Tile(rowIdx, outStart, curOut, curIn, asVal, absmax);
            } else {
                ProcessMode1Tile(rowIdx, outStart, curOut, curIn, asVal, absmax);
            }
        }
    }

    // -----------------------------------------------------------------------
    // Mode 0: halves split + Swish
    // front = xf32[:, :H], back = xf32[:, H:]
    // glu, lin = (front, back) or (back, front)
    // sw = lin * (glu * sigmoid(glu))
    // -----------------------------------------------------------------------
    __aicore__ inline void ProcessMode0Tile(
        int32_t rowIdx, int32_t outStart, int32_t curOut, int32_t curIn,
        float asVal, float &absmax)
    {
        // --- Load x front: X[row, outStart:outStart+curOut] (int32) ---
        xInLocal_ = xInQueue_.AllocTensor<int32_t>();
        LoadGmToUbPad(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N_ + outStart],
                      static_cast<uint32_t>(curOut));
        xInQueue_.EnQue(xInLocal_);

        // --- Load x back: X[row, H+outStart:H+outStart+curOut] (int32) ---
        // We wait for front DeQue before reusing xInQueue, or use separate queue
        // Use single queue with sequential processing: load front, process, then load back

        // Wait and process front
        {
            xInLocal_ = xInQueue_.DeQue<int32_t>();

            // Dequant front: int32 → fp32 → * ws_front * as
            float *deqFrontPtr = deqBuf_.Get<float>();
            AscendC::LocalTensor<float> deqFront(deqFrontPtr, curOut);
            AscendC::Cast(deqFront, xInLocal_, AscendC::RoundMode::CAST_NONE, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Load ws front
            wsInLocal_ = wsInQueue_.AllocTensor<float>();
            LoadGmToUbPad(wsInLocal_, wsGM_[static_cast<uint64_t>(outStart)],
                          static_cast<uint32_t>(curOut));
            wsInQueue_.EnQue(wsInLocal_);
            wsInLocal_ = wsInQueue_.DeQue<float>();

            AscendC::Mul(deqFront, deqFront, wsInLocal_, curOut);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Muls(deqFront, deqFront, asVal, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            wsInQueue_.FreeTensor(wsInLocal_);
            xInQueue_.FreeTensor(xInLocal_);
        }

        // Load and process back
        {
            xInLocal_ = xInQueue_.AllocTensor<int32_t>();
            LoadGmToUbPad(xInLocal_,
                          xGM_[static_cast<uint64_t>(rowIdx) * N_ + H_ + outStart],
                          static_cast<uint32_t>(curOut));
            xInQueue_.EnQue(xInLocal_);
            xInLocal_ = xInQueue_.DeQue<int32_t>();

            // Dequant back: int32 → fp32 → * ws_back * as
            float *deqBackPtr = deqBuf_.Get<float>() + curOut;  // use second half
            AscendC::LocalTensor<float> deqBack(deqBackPtr, curOut);
            AscendC::Cast(deqBack, xInLocal_, AscendC::RoundMode::CAST_NONE, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Load ws back
            wsInLocal_ = wsInQueue_.AllocTensor<float>();
            LoadGmToUbPad(wsInLocal_,
                          wsGM_[static_cast<uint64_t>(H_ + outStart)],
                          static_cast<uint32_t>(curOut));
            wsInQueue_.EnQue(wsInLocal_);
            wsInLocal_ = wsInQueue_.DeQue<float>();

            AscendC::Mul(deqBack, deqBack, wsInLocal_, curOut);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Muls(deqBack, deqBack, asVal, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            wsInQueue_.FreeTensor(wsInLocal_);
            xInQueue_.FreeTensor(xInLocal_);

            // --- SwiGLU computation ---
            float *frontPtr = deqBuf_.Get<float>();
            float *backPtr = deqBuf_.Get<float>() + curOut;
            AscendC::LocalTensor<float> frontTensor(frontPtr, curOut);
            AscendC::LocalTensor<float> backTensor(backPtr, curOut);

            float *gluPtr, *linPtr;
            if (activateLeft_) {
                gluPtr = frontPtr; linPtr = backPtr;
            } else {
                gluPtr = backPtr; linPtr = frontPtr;
            }
            AscendC::LocalTensor<float> gluTensor(gluPtr, curOut);
            AscendC::LocalTensor<float> linTensor(linPtr, curOut);

            // swish = glu * sigmoid(glu)
            float *sigPtr = sigBuf_.Get<float>();
            AscendC::LocalTensor<float> sig(sigPtr, curOut);

            // sigmoid(glu) = 1 / (1 + exp(-glu))
            AscendC::Muls(sig, gluTensor, -1.0f, curOut);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Exp(sig, sig, curOut);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Adds(sig, sig, 1.0f, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            float *swishPtr = tmpBuf_.Get<float>();
            AscendC::LocalTensor<float> swish(swishPtr, curOut);
            AscendC::Div(swish, sig, sig, curOut);  // dst=1.0/sig = swish=glu*sigmoid?
            // Wait - we need glu * sigmoid(glu). sigmoid = 1/(1+exp(-x))
            // We computed sig = 1+exp(-glu). We need 1/sig = sigmoid.
            // But wait, we set sig = sig as both src to Div which does dst = src0/src1 = 1.0? No.
            // Div(dst, src0, src1) = dst = src0 / src1 per-element.
            // We need dst = 1.0 / sig = sigmoid(glu).
            // So we need: AscendC::Div(swish, <ones>, sig, curOut)
            // But we don't have ones buffer. Let me use Reciprocal instead.

            // Actually, let me fix: Use Reciprocal(sig) to get 1/sig
            // And then Mul(swish, glu, sig) to get glu * sigmoid
            AscendC::PipeBarrier<PIPE_V>();
        }

        // Actually, let me redo this with proper approach. Let me first get sigmoid right.
        // sigmoid(x) = 1 / (1 + exp(-x))
        // Let tmp = exp(-glu)
        // Then tmp = 1 + tmp
        // Then swish = glu / tmp

        // Complete rewrite of SwiGLU section
        float *gluFinal, *linFinal;
        {
            float *frontPtr2 = deqBuf_.Get<float>();
            float *backPtr2 = deqBuf_.Get<float>() + curOut;

            if (activateLeft_) {
                gluFinal = frontPtr2; linFinal = backPtr2;
            } else {
                gluFinal = backPtr2; linFinal = frontPtr2;
            }
        }

        AscendC::LocalTensor<float> gluF(gluFinal, curOut);
        AscendC::LocalTensor<float> linF(linFinal, curOut);

        // sigmoid(glu) = 1 / (1 + exp(-glu))
        float *sigPtr = sigBuf_.Get<float>();
        AscendC::LocalTensor<float> sig(sigPtr, curOut);
        AscendC::Muls(sig, gluF, -1.0f, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Exp(sig, sig, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Adds(sig, sig, 1.0f, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // sigmoid = Reciprocal(sig) = 1 / (1+exp(-glu))
        float *sigmoidPtr = tmpBuf_.Get<float>();
        AscendC::LocalTensor<float> sigmoidT(sigmoidPtr, curOut);
        AscendC::Reciprocal(sigmoidT, sig, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // sw = lin * (glu * sigmoid)
        float *swPtr = swBuf_.Get<float>();
        AscendC::LocalTensor<float> sw(swPtr, curOut);
        AscendC::Mul(sw, gluF, sigmoidT, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(sw, sw, linF, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // --- Smooth quant: sw * quant_scale ---
        LoadAndApplyQuantScale(sw, outStart, curOut);

        // --- Store to smoothBuf and track absmax ---
        AccumulateSmoothOutput(sw, outStart, curOut, absmax);
    }

    // -----------------------------------------------------------------------
    // Mode 1: even/odd split + gpt-oss variant
    // glu = x[:, 0::2], lin = x[:, 1::2]
    // glu_c = min(glu, L), lin_c = clamp(lin, -L, L)
    // sw = glu_c * sigmoid(alpha * glu_c) * (lin_c + beta)
    // -----------------------------------------------------------------------
    __aicore__ inline void ProcessMode1Tile(
        int32_t rowIdx, int32_t outStart, int32_t curOut, int32_t curIn,
        float asVal, float &absmax)
    {
        int32_t inStart = outStart * 2;

        // --- Load glu (even indices: 0,2,4,...) ---
        xInLocal_ = xInQueue_.AllocTensor<int32_t>();
        {
            // Load with stride: skip every other element
            AscendC::DataCopyExtParams copyParams{
                static_cast<uint16_t>(curOut),
                static_cast<uint16_t>(sizeof(int32_t)),
                static_cast<uint16_t>(2 * sizeof(int32_t)),
                static_cast<uint16_t>(sizeof(int32_t)),
                0};
            AscendC::DataCopyPadExtParams<int32_t> padParams{true, 0, 0, 0};
            AscendC::DataCopyPad(xInLocal_,
                                 xGM_[static_cast<uint64_t>(rowIdx) * N_ + inStart],
                                 copyParams, padParams);
        }
        xInQueue_.EnQue(xInLocal_);
        xInLocal_ = xInQueue_.DeQue<int32_t>();

        // Dequant glu: int32 → fp32
        float *gluDeqPtr = deqBuf_.Get<float>();
        AscendC::LocalTensor<float> gluDeq(gluDeqPtr, curOut);
        AscendC::Cast(gluDeq, xInLocal_, AscendC::RoundMode::CAST_NONE, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // Load ws for glu (even stride)
        wsInLocal_ = wsInQueue_.AllocTensor<float>();
        {
            AscendC::DataCopyExtParams copyParams{
                static_cast<uint16_t>(curOut),
                static_cast<uint16_t>(sizeof(float)),
                static_cast<uint16_t>(2 * sizeof(float)),
                static_cast<uint16_t>(sizeof(float)),
                0};
            AscendC::DataCopyPadExtParams<float> padParams{true, 0, 0, 0.0f};
            AscendC::DataCopyPad(wsInLocal_, wsGM_[static_cast<uint64_t>(inStart)],
                                 copyParams, padParams);
        }
        wsInQueue_.EnQue(wsInLocal_);
        wsInLocal_ = wsInQueue_.DeQue<float>();

        AscendC::Mul(gluDeq, gluDeq, wsInLocal_, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(gluDeq, gluDeq, asVal, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        wsInQueue_.FreeTensor(wsInLocal_);
        xInQueue_.FreeTensor(xInLocal_);

        // --- Load lin (odd indices: 1,3,5,...) ---
        xInLocal_ = xInQueue_.AllocTensor<int32_t>();
        {
            AscendC::DataCopyExtParams copyParams{
                static_cast<uint16_t>(curOut),
                static_cast<uint16_t>(sizeof(int32_t)),
                static_cast<uint16_t>(2 * sizeof(int32_t)),
                static_cast<uint16_t>(sizeof(int32_t)),
                0};
            AscendC::DataCopyPadExtParams<int32_t> padParams{true, 0, 0, 0};
            AscendC::DataCopyPad(xInLocal_,
                                 xGM_[static_cast<uint64_t>(rowIdx) * N_ + inStart + 1],
                                 copyParams, padParams);
        }
        xInQueue_.EnQue(xInLocal_);
        xInLocal_ = xInQueue_.DeQue<int32_t>();

        // Dequant lin
        float *linDeqPtr = deqBuf_.Get<float>() + curOut;
        AscendC::LocalTensor<float> linDeq(linDeqPtr, curOut);
        AscendC::Cast(linDeq, xInLocal_, AscendC::RoundMode::CAST_NONE, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // Load ws for lin (odd stride)
        wsInLocal_ = wsInQueue_.AllocTensor<float>();
        {
            AscendC::DataCopyExtParams copyParams{
                static_cast<uint16_t>(curOut),
                static_cast<uint16_t>(sizeof(float)),
                static_cast<uint16_t>(2 * sizeof(float)),
                static_cast<uint16_t>(sizeof(float)),
                0};
            AscendC::DataCopyPadExtParams<float> padParams{true, 0, 0, 0.0f};
            AscendC::DataCopyPad(wsInLocal_, wsGM_[static_cast<uint64_t>(inStart + 1)],
                                 copyParams, padParams);
        }
        wsInQueue_.EnQue(wsInLocal_);
        wsInLocal_ = wsInQueue_.DeQue<float>();

        AscendC::Mul(linDeq, linDeq, wsInLocal_, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(linDeq, linDeq, asVal, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        wsInQueue_.FreeTensor(wsInLocal_);
        xInQueue_.FreeTensor(xInLocal_);

        // --- Mode 1 computation ---
        float *gluPtr = deqBuf_.Get<float>();
        float *linPtr = deqBuf_.Get<float>() + curOut;
        AscendC::LocalTensor<float> glu(gluPtr, curOut);
        AscendC::LocalTensor<float> lin(linPtr, curOut);

        // glu_c = min(glu, clampLimit)
        float *gluCPtr = swBuf_.Get<float>();
        AscendC::LocalTensor<float> gluC(gluCPtr, curOut);
        AscendC::Mins(gluC, glu, clampLimit_, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // lin_c = clamp(lin, -L, L): max(-L, min(lin, L))
        float *linCTmpPtr = tmpBuf_.Get<float>();
        AscendC::LocalTensor<float> linCTmp(linCTmpPtr, curOut);
        AscendC::Mins(linCTmp, lin, clampLimit_, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Maxs(linCTmp, linCTmp, -clampLimit_, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // sigmoid(alpha * glu_c)
        float *sigArgPtr = sigBuf_.Get<float>();
        AscendC::LocalTensor<float> sigArg(sigArgPtr, curOut);
        AscendC::Muls(sigArg, gluC, gluAlpha_, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(sigArg, sigArg, -1.0f, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Exp(sigArg, sigArg, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Adds(sigArg, sigArg, 1.0f, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        float *sigmoidPtr = sigBuf_.Get<float>();
        AscendC::LocalTensor<float> sigmoidL(sigmoidPtr, curOut);
        AscendC::Reciprocal(sigmoidL, sigArg, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // lin_c + beta
        AscendC::Adds(linCTmp, linCTmp, gluBeta_, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // sw = glu_c * sigmoid * (lin_c + beta)
        float *swPtr = swBuf_.Get<float>();
        AscendC::LocalTensor<float> sw(swPtr, curOut);
        AscendC::Mul(sw, gluC, sigmoidL, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(sw, sw, linCTmp, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // --- Smooth quant ---
        LoadAndApplyQuantScale(sw, outStart, curOut);

        // --- Store and track absmax ---
        AccumulateSmoothOutput(sw, outStart, curOut, absmax);
    }

    __aicore__ inline void LoadAndApplyQuantScale(
        AscendC::LocalTensor<float> &sw, int32_t outStart, int32_t curOut)
    {
        float *qsPtr = qsBuf_.Get<float>();
        AscendC::LocalTensor<float> qs(qsPtr, curOut);
        LoadGmToUbPad(qs, qsGM_[static_cast<uint64_t>(outStart)],
                      static_cast<uint32_t>(curOut));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        AscendC::Mul(sw, sw, qs, curOut);
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void AccumulateSmoothOutput(
        AscendC::LocalTensor<float> &sw, int32_t outStart, int32_t curOut,
        float &absmax)
    {
        // Copy smooth quant result to smoothBuf at position outStart
        float *smoothPtr = smoothBuf_.Get<float>() + outStart;
        AscendC::LocalTensor<float> smoothDst(smoothPtr, curOut);
        AscendC::DataCopy(smoothDst, sw, curOut);
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        // Compute absmax for this tile
        float *absTilePtr = quantTmp_.Get<float>();
        AscendC::LocalTensor<float> absTile(absTilePtr, curOut);
        AscendC::Abs(absTile, sw, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        float *reducePtr = reduceTmp_.Get<uint8_t>();
        AscendC::LocalTensor<uint8_t> reduce(reducePtr, 2 * curOut * sizeof(float));
        float *absmaxPtr = absmaxBuf_.Get<float>();
        AscendC::LocalTensor<float> absmaxTile(absmaxPtr, 1);
        AscendC::ReduceMax<float>(absmaxTile, absTile, reduce, curOut);
        AscendC::PipeBarrier<PIPE_ALL>();

        float tileMax = absmaxTile.GetValue(0);
        if (tileMax > absmax) {
            absmax = tileMax;
        }
    }

    // -----------------------------------------------------------------------
    // Quantize pass: smooth → /scale → round → clamp → int8 → write
    // -----------------------------------------------------------------------
    __aicore__ inline void QuantizePass(int32_t rowIdx, float safeScale)
    {
        int32_t hTiles = CeilDiv(H_, TILE_H);
        float invScale = 1.0f / safeScale;

        for (int32_t ht = 0; ht < hTiles; ++ht) {
            int32_t outStart = ht * TILE_H;
            int32_t curOut = (outStart + TILE_H <= H_) ? TILE_H : (H_ - outStart);

            // Read smooth output from smoothBuf
            float *smoothPtr = smoothBuf_.Get<float>() + outStart;
            AscendC::LocalTensor<float> smoothVal(smoothPtr, curOut);

            // Multiply by 1/scale
            float *quantPtr = quantTmp_.Get<float>();
            AscendC::LocalTensor<float> quant(quantPtr, curOut);
            AscendC::Muls(quant, smoothVal, invScale, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Round to nearest int
            AscendC::Cast(quant, quant, AscendC::RoundMode::CAST_ROUND, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Clamp to [-128, 127]
            AscendC::Mins(quant, quant, 127.0f, curOut);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Maxs(quant, quant, -128.0f, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Cast to int8
            AscendC::Cast(quant, quant, AscendC::RoundMode::CAST_NONE, curOut);
            AscendC::PipeBarrier<PIPE_V>();
            // Reinterpret to int8
            int8_t *quantI8Ptr = reinterpret_cast<int8_t *>(quantTmp_.Get<float>());
            AscendC::LocalTensor<int8_t> quantI8(quantI8Ptr, curOut);

            // Write to GM
            StoreUbToGmPad(yGM_[static_cast<uint64_t>(rowIdx) * H_ + outStart],
                           quantI8, static_cast<uint32_t>(curOut));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
        }
    }

private:
    // Kernel parameters
    int32_t M_ = 0;
    int32_t N_ = 0;
    int32_t H_ = 0;
    int32_t blockM_ = 0;
    int32_t usedCoreNum_ = 0;
    int32_t tasksPerCore_ = 0;
    int32_t swigluMode_ = 0;
    int32_t activateLeft_ = 0;
    float clampLimit_ = 7.0f;
    float gluAlpha_ = 1.702f;
    float gluBeta_ = 1.0f;
    float inv127_ = 0.007874016f;
    int32_t vecNum_ = 2;

    // Global tensors
    AscendC::GlobalTensor<int32_t> xGM_;
    AscendC::GlobalTensor<float> wsGM_;
    AscendC::GlobalTensor<float> asGM_;
    AscendC::GlobalTensor<float> qsGM_;
    AscendC::GlobalTensor<int8_t> yGM_;
    AscendC::GlobalTensor<float> rsGM_;

    // Pipe and buffers
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> wsInQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smoothBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmp_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> absmaxBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> quantTmp_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> qsBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> deqBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> swBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sigBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;

    // Local tensors
    AscendC::LocalTensor<int32_t> xInLocal_;
    AscendC::LocalTensor<float> wsInLocal_;
};

// =========================================================================
// Kernel entry point
// =========================================================================

extern "C" __global__ __aicore__ void dequant_swiglu_quant(
    GM_ADDR x, GM_ADDR weightScale, GM_ADDR activationScale,
    GM_ADDR quantScale, GM_ADDR y, GM_ADDR rowScale,
    int32_t M, int32_t N, int32_t H,
    int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
    int64_t swigluMode, int64_t activateLeft,
    float clampLimit, float gluAlpha, float gluBeta)
{
    DequantSwigluQuantKernel kernel;
    kernel.Init(x, weightScale, activationScale, quantScale, y, rowScale,
                M, N, H, blockM, usedCoreNum, tasksPerCore,
                swigluMode, activateLeft, clampLimit, gluAlpha, gluBeta);
    kernel.Process();
}
