// DequantSwigluQuant op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_dequant_swiglu_quant.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_M = 64;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

std::vector<at::Tensor> dequant_swiglu_quant(
    const at::Tensor &x,
    const at::Tensor &weightScale,
    const at::Tensor &activationScale,
    const at::Tensor &quantScale,
    int64_t swigluMode,
    int64_t activateLeft,
    double clampLimit,
    double gluAlpha,
    double gluBeta)
{
    // Input validation
    TORCH_CHECK(x.dim() == 2, "x must be [M, N]");
    TORCH_CHECK(x.scalar_type() == at::kInt, "x must be int32");
    TORCH_CHECK(weightScale.scalar_type() == at::kFloat,
                "weight_scale must be float32");
    TORCH_CHECK(activationScale.scalar_type() == at::kFloat,
                "activation_scale must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weightScale.is_contiguous(), "weight_scale must be contiguous");
    TORCH_CHECK(activationScale.is_contiguous(), "activation_scale must be contiguous");

    int32_t M = static_cast<int32_t>(x.sizes()[0]);
    int32_t N = static_cast<int32_t>(x.sizes()[1]);
    int32_t H = N / 2;

    // Convert quant_scale to float32 if needed
    at::Tensor qsFp32;
    if (quantScale.scalar_type() != at::kFloat) {
        qsFp32 = quantScale.to(at::kFloat).contiguous();
    } else {
        qsFp32 = quantScale.contiguous();
    }

    // Tiling computation
    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,
                                            std::max<int32_t>(1, mNum));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // Output allocation
    at::Tensor y = at::empty({M, H}, at::TensorOptions().dtype(at::kByte).device(x.device()));
    at::Tensor rowScale = at::empty({M}, at::TensorOptions().dtype(at::kFloat).device(x.device()));

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t blockM = DEFAULT_BLOCK_M;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    float clampLimitVal = static_cast<float>(clampLimit);
    float gluAlphaVal = static_cast<float>(gluAlpha);
    float gluBetaVal = static_cast<float>(gluBeta);
    int64_t swigluModeVal = swigluMode;
    int64_t activateLeftVal = activateLeft;
    int64_t quantModeVal = 1;  // per-row dynamic quant

    EXEC_KERNEL_CMD(dequant_swiglu_quant, blockDim,
                    x, qsFp32, weightScale, activationScale, y, rowScale,
                    M, N, H, blockM, usedCoreNum, tasksPerCore,
                    swigluModeVal, activateLeftVal,
                    clampLimitVal, gluAlphaVal, gluBetaVal);

    return {y, rowScale};
}

}  // namespace ascend_kernel
