// AscendC DequantSwigluQuant kernel — fused dequant(int32->fp32) + SwiGLU + per-row int8 quant
// Single strategy: per-row tile-by-tile processing along H dimension.
//
// Two-pass design:
//   Pass 1: compute swiglu per tile along H, smooth quant, track absmax
//   Compute safe_scale from absmax
//   Pass 2: recompute swiglu per tile, smooth quant, quantize (div by scale, round, clamp, cast to int8)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_H = 512;

// ===========================================================================
// Inline helpers
// ===========================================================================

__aicore__ inline int32_t CeilDiv(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUbPad(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGmPad(
    AscendC::GlobalTensor<T> &dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// Load with stride: read every N-th element from GM
template <typename T>
__aicore__ inline void LoadGmToUbStrided(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count,
    uint32_t elementStride)
{
    AscendC::DataCopyExtParams copyParams{
        static_cast<uint16_t>(count),
        static_cast<uint16_t>(sizeof(T)),
        static_cast<uint16_t>(elementStride * sizeof(T)),
        static_cast<uint16_t>(sizeof(T)),
        0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

// ===========================================================================
// Kernel class
// ===========================================================================

class DequantSwigluQuantKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR weightScale, GM_ADDR activationScale,
        GM_ADDR quantScale, GM_ADDR y, GM_ADDR rowScale,
        int32_t M, int32_t N, int32_t H,
        int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
        int64_t swigluMode, int64_t activateLeft,
        float clampLimit, float gluAlpha, float gluBeta)
    {
        this->M_ = M;
        this->N_ = N;
        this->H_ = H;
        this->blockM_ = blockM;
        this->usedCoreNum_ = usedCoreNum;
        this->tasksPerCore_ = tasksPerCore;
        this->swigluMode_ = static_cast<int32_t>(swigluMode);
        this->activateLeft_ = static_cast<int32_t>(activateLeft);
        this->clampLimit_ = clampLimit;
        this->gluAlpha_ = gluAlpha;
        this->gluBeta_ = gluBeta;
        this->inv127_ = 1.0f / 127.0f;
        this->vecNum_ = AscendC::GetSubBlockNum();

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(x),
                             static_cast<uint64_t>(M) * N);
        wsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(weightScale),
                              static_cast<uint64_t>(1) * N);
        asGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(activationScale),
                              static_cast<uint64_t>(M) * 1);
        qsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(quantScale),
                              static_cast<uint64_t>(1) * H);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y),
                             static_cast<uint64_t>(M) * H);
        rsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(rowScale),
                              static_cast<uint64_t>(M));

        if ASCEND_IS_AIV {
            InitBuffers();
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx() / vecNum_;
            int32_t subBlockIdx = AscendC::GetSubBlockIdx();
            int32_t subBlockRows = blockM_ / vecNum_;
            int32_t mNum = CeilDiv(M_, blockM_);

            for (int32_t localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                int32_t bx = coreIdx * tasksPerCore_ + localIdx;
                if (bx >= mNum) { continue; }

                for (int32_t row = 0; row < subBlockRows; ++row) {
                    int32_t rowIdx = bx * blockM_ + subBlockIdx * subBlockRows + row;
                    if (rowIdx >= M_) { continue; }
                    ProcessRow(rowIdx);
                }
            }
        }
    }

private:
    // -----------------------------------------------------------------------
    // Buffer initialization
    // -----------------------------------------------------------------------
    __aicore__ inline void InitBuffers()
    {
        // Reduce temp for absmax (2x element count)
        pipe_.InitBuffer(reduceTmp_, 2 * TILE_H * sizeof(float));
        // Absmax scalar
        pipe_.InitBuffer(absmaxBuf_, sizeof(float));
        // Input queues (1 tile = TILE_H elements of int32 or float32)
        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, TILE_H * sizeof(int32_t));
        pipe_.InitBuffer(wsInQueue_, BUFFER_NUM, TILE_H * sizeof(float));
        // Dequant buffers (fp32)
        pipe_.InitBuffer(deqFrontBuf_, TILE_H * sizeof(float));
        pipe_.InitBuffer(deqBackBuf_, TILE_H * sizeof(float));
        // SwiGLU intermediate
        pipe_.InitBuffer(swBuf_, TILE_H * sizeof(float));
        pipe_.InitBuffer(sigBuf_, TILE_H * sizeof(float));
        pipe_.InitBuffer(tmpBuf_, TILE_H * sizeof(float));
        // Quant scale tile
        pipe_.InitBuffer(qsBuf_, TILE_H * sizeof(float));
    }

    // -----------------------------------------------------------------------
    // Per-row processing (two-pass)
    // -----------------------------------------------------------------------
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        float asVal = asGM_.GetValue(rowIdx);

        // === Pass 1: compute absmax ===
        float absmax = ComputeAbsmax(rowIdx, asVal);

        // === Compute safe scale ===
        float scale = absmax * inv127_;
        float safeScale = (scale > 0.0f) ? scale : 1.0f;
        float invScale = 1.0f / safeScale;
        rsGM_.SetValue(rowIdx, safeScale);

        // === Pass 2: compute + quantize ===
        ComputeAndQuantize(rowIdx, asVal, invScale);
    }

    __aicore__ inline float ComputeAbsmax(int32_t rowIdx, float asVal)
    {
        float absmax = 0.0f;
        int32_t hTiles = CeilDiv(H_, TILE_H);

        for (int32_t ht = 0; ht < hTiles; ++ht) {
            int32_t outStart = ht * TILE_H;
            int32_t curOut = (outStart + TILE_H <= H_) ? TILE_H : (H_ - outStart);

            // Compute SwiGLU for this tile
            ComputeSwigluTile(rowIdx, outStart, curOut, asVal);

            // Apply smooth quant: sw * quant_scale
            AscendC::LocalTensor<float> swLocal = swBuf_.Get<float>();
            AscendC::LocalTensor<float> qsLocal = qsBuf_.Get<float>();
            LoadGmToUbPad(qsLocal, qsGM_[static_cast<uint64_t>(outStart)],
                          static_cast<uint32_t>(curOut));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            AscendC::Mul(swLocal, swLocal, qsLocal, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // absmax for this tile
            AscendC::LocalTensor<float> absTile = tmpBuf_.Get<float>();
            AscendC::Abs(absTile, swLocal, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::LocalTensor<uint8_t> reduceLocal = reduceTmp_.Get<uint8_t>();
            AscendC::LocalTensor<float> absmaxLocal = absmaxBuf_.Get<float>();
            AscendC::ReduceMax<float>(absmaxLocal, absTile, reduceLocal, curOut);
            AscendC::PipeBarrier<PIPE_ALL>();

            float tileMax = absmaxLocal.GetValue(0);
            if (tileMax > absmax) {
                absmax = tileMax;
            }
        }

        return absmax;
    }

    __aicore__ inline void ComputeAndQuantize(
        int32_t rowIdx, float asVal, float invScale)
    {
        int32_t hTiles = CeilDiv(H_, TILE_H);

        for (int32_t ht = 0; ht < hTiles; ++ht) {
            int32_t outStart = ht * TILE_H;
            int32_t curOut = (outStart + TILE_H <= H_) ? TILE_H : (H_ - outStart);

            // Recompute SwiGLU for this tile
            ComputeSwigluTile(rowIdx, outStart, curOut, asVal);

            // Smooth quant
            AscendC::LocalTensor<float> swLocal = swBuf_.Get<float>();
            AscendC::LocalTensor<float> qsLocal = qsBuf_.Get<float>();
            LoadGmToUbPad(qsLocal, qsGM_[static_cast<uint64_t>(outStart)],
                          static_cast<uint32_t>(curOut));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            AscendC::Mul(swLocal, swLocal, qsLocal, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Quantize: * invScale
            AscendC::Muls(swLocal, swLocal, invScale, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Round to nearest integer
            AscendC::Cast(swLocal, swLocal, AscendC::RoundMode::CAST_ROUND, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Clamp to [-128, 127]
            AscendC::LocalTensor<float> clampLocal = deqFrontBuf_.Get<float>();
            AscendC::Mins(clampLocal, swLocal, 127.0f, curOut);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Maxs(clampLocal, clampLocal, -128.0f, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Cast to int8 (same underlying bytes, reinterpret)
            AscendC::Cast(clampLocal, clampLocal, AscendC::RoundMode::CAST_NONE, curOut);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::LocalTensor<int8_t> i8Local =
                clampLocal.template ReinterpretCast<int8_t>();

            // Write to GM
            StoreUbToGmPad(yGM_[static_cast<uint64_t>(rowIdx) * H_ + outStart],
                           i8Local, static_cast<uint32_t>(curOut));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
        }
    }

    // -----------------------------------------------------------------------
    // Compute SwiGLU for one tile (result in swBuf_)
    // -----------------------------------------------------------------------
    __aicore__ inline void ComputeSwigluTile(
        int32_t rowIdx, int32_t outStart, int32_t curOut, float asVal)
    {
        if (swigluMode_ == 0) {
            ComputeMode0(rowIdx, outStart, curOut, asVal);
        } else {
            ComputeMode1(rowIdx, outStart, curOut, asVal);
        }
    }

    // -----------------------------------------------------------------------
    // Mode 0: halves split + Swish
    // -----------------------------------------------------------------------
    __aicore__ inline void ComputeMode0(
        int32_t rowIdx, int32_t outStart, int32_t curOut, float asVal)
    {
        // --- Load + dequant front ---
        xInLocal_ = xInQueue_.AllocTensor<int32_t>();
        LoadGmToUbPad(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N_ + outStart],
                      static_cast<uint32_t>(curOut));
        xInQueue_.EnQue(xInLocal_);
        xInLocal_ = xInQueue_.DeQue<int32_t>();

        wsInLocal_ = wsInQueue_.AllocTensor<float>();
        LoadGmToUbPad(wsInLocal_, wsGM_[static_cast<uint64_t>(outStart)],
                      static_cast<uint32_t>(curOut));
        wsInQueue_.EnQue(wsInLocal_);
        wsInLocal_ = wsInQueue_.DeQue<float>();

        AscendC::LocalTensor<float> frontLocal = deqFrontBuf_.Get<float>();
        AscendC::Cast(frontLocal, xInLocal_, AscendC::RoundMode::CAST_NONE, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(frontLocal, frontLocal, wsInLocal_, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(frontLocal, frontLocal, asVal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        wsInQueue_.FreeTensor(wsInLocal_);
        xInQueue_.FreeTensor(xInLocal_);

        // --- Load + dequant back ---
        xInLocal_ = xInQueue_.AllocTensor<int32_t>();
        LoadGmToUbPad(xInLocal_,
                      xGM_[static_cast<uint64_t>(rowIdx) * N_ + H_ + outStart],
                      static_cast<uint32_t>(curOut));
        xInQueue_.EnQue(xInLocal_);
        xInLocal_ = xInQueue_.DeQue<int32_t>();

        wsInLocal_ = wsInQueue_.AllocTensor<float>();
        LoadGmToUbPad(wsInLocal_, wsGM_[static_cast<uint64_t>(H_ + outStart)],
                      static_cast<uint32_t>(curOut));
        wsInQueue_.EnQue(wsInLocal_);
        wsInLocal_ = wsInQueue_.DeQue<float>();

        AscendC::LocalTensor<float> backLocal = deqBackBuf_.Get<float>();
        AscendC::Cast(backLocal, xInLocal_, AscendC::RoundMode::CAST_NONE, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(backLocal, backLocal, wsInLocal_, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(backLocal, backLocal, asVal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        wsInQueue_.FreeTensor(wsInLocal_);
        xInQueue_.FreeTensor(xInLocal_);

        // --- SwiGLU ---
        AscendC::LocalTensor<float> gluLocal = deqFrontBuf_.Get<float>();
        AscendC::LocalTensor<float> linLocal = deqBackBuf_.Get<float>();

        if (!activateLeft_) {
            // Swap front/back so glu=back, lin=front
            AscendC::LocalTensor<float> swpTmp = swBuf_.Get<float>();
            AscendC::DataCopy(swpTmp, gluLocal, curOut);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            AscendC::DataCopy(gluLocal, linLocal, curOut);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            AscendC::DataCopy(linLocal, swpTmp, curOut);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
        }

        // sigmoid(glu) = 1 / (1 + exp(-glu))
        AscendC::LocalTensor<float> sigLocal = sigBuf_.Get<float>();
        AscendC::Muls(sigLocal, gluLocal, -1.0f, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Exp(sigLocal, sigLocal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Adds(sigLocal, sigLocal, 1.0f, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Reciprocal(sigLocal, sigLocal, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // sw = lin * (glu * sigmoid)
        AscendC::LocalTensor<float> swLocal = swBuf_.Get<float>();
        AscendC::Mul(swLocal, gluLocal, sigLocal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(swLocal, swLocal, linLocal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
    }

    // -----------------------------------------------------------------------
    // Mode 1: even/odd split + gpt-oss variant
    // -----------------------------------------------------------------------
    __aicore__ inline void ComputeMode1(
        int32_t rowIdx, int32_t outStart, int32_t curOut, float asVal)
    {
        int32_t inStart = outStart * 2;

        // --- Load + dequant glu (even indices) ---
        xInLocal_ = xInQueue_.AllocTensor<int32_t>();
        LoadGmToUbStrided(xInLocal_,
                          xGM_[static_cast<uint64_t>(rowIdx) * N_ + inStart],
                          static_cast<uint32_t>(curOut), 2);
        xInQueue_.EnQue(xInLocal_);
        xInLocal_ = xInQueue_.DeQue<int32_t>();

        wsInLocal_ = wsInQueue_.AllocTensor<float>();
        LoadGmToUbStrided(wsInLocal_, wsGM_[static_cast<uint64_t>(inStart)],
                          static_cast<uint32_t>(curOut), 2);
        wsInQueue_.EnQue(wsInLocal_);
        wsInLocal_ = wsInQueue_.DeQue<float>();

        AscendC::LocalTensor<float> gluLocal = deqFrontBuf_.Get<float>();
        AscendC::Cast(gluLocal, xInLocal_, AscendC::RoundMode::CAST_NONE, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(gluLocal, gluLocal, wsInLocal_, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(gluLocal, gluLocal, asVal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        wsInQueue_.FreeTensor(wsInLocal_);
        xInQueue_.FreeTensor(xInLocal_);

        // --- Load + dequant lin (odd indices) ---
        xInLocal_ = xInQueue_.AllocTensor<int32_t>();
        LoadGmToUbStrided(xInLocal_,
                          xGM_[static_cast<uint64_t>(rowIdx) * N_ + inStart + 1],
                          static_cast<uint32_t>(curOut), 2);
        xInQueue_.EnQue(xInLocal_);
        xInLocal_ = xInQueue_.DeQue<int32_t>();

        wsInLocal_ = wsInQueue_.AllocTensor<float>();
        LoadGmToUbStrided(wsInLocal_, wsGM_[static_cast<uint64_t>(inStart + 1)],
                          static_cast<uint32_t>(curOut), 2);
        wsInQueue_.EnQue(wsInLocal_);
        wsInLocal_ = wsInQueue_.DeQue<float>();

        AscendC::LocalTensor<float> linLocal = deqBackBuf_.Get<float>();
        AscendC::Cast(linLocal, xInLocal_, AscendC::RoundMode::CAST_NONE, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(linLocal, linLocal, wsInLocal_, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(linLocal, linLocal, asVal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        wsInQueue_.FreeTensor(wsInLocal_);
        xInQueue_.FreeTensor(xInLocal_);

        // --- Mode 1 computation ---
        // glu_c = min(glu, L)
        AscendC::LocalTensor<float> gluCLocal = tmpBuf_.Get<float>();
        AscendC::Mins(gluCLocal, gluLocal, clampLimit_, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // lin_c = clamp(lin, -L, L): max(-L, min(lin, L))
        AscendC::Mins(linLocal, linLocal, clampLimit_, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Maxs(linLocal, linLocal, -clampLimit_, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // sigmoid(alpha * glu_c)
        AscendC::LocalTensor<float> sigLocal = sigBuf_.Get<float>();
        AscendC::Muls(sigLocal, gluCLocal, gluAlpha_, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(sigLocal, sigLocal, -1.0f, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Exp(sigLocal, sigLocal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Adds(sigLocal, sigLocal, 1.0f, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Reciprocal(sigLocal, sigLocal, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // lin_c + beta
        AscendC::Adds(linLocal, linLocal, gluBeta_, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // sw = glu_c * sigmoid * (lin_c + beta)
        AscendC::LocalTensor<float> swLocal = swBuf_.Get<float>();
        AscendC::Mul(swLocal, gluCLocal, sigLocal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(swLocal, swLocal, linLocal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
    }

private:
    // Kernel parameters
    int32_t M_ = 0;
    int32_t N_ = 0;
    int32_t H_ = 0;
    int32_t blockM_ = 0;
    int32_t usedCoreNum_ = 0;
    int32_t tasksPerCore_ = 0;
    int32_t swigluMode_ = 0;
    int32_t activateLeft_ = 0;
    float clampLimit_ = 7.0f;
    float gluAlpha_ = 1.702f;
    float gluBeta_ = 1.0f;
    float inv127_ = 0.007874016f;
    int32_t vecNum_ = 2;

    // Global tensors
    AscendC::GlobalTensor<int32_t> xGM_;
    AscendC::GlobalTensor<float> wsGM_;
    AscendC::GlobalTensor<float> asGM_;
    AscendC::GlobalTensor<float> qsGM_;
    AscendC::GlobalTensor<int8_t> yGM_;
    AscendC::GlobalTensor<float> rsGM_;

    // Pipe and buffers
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> wsInQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmp_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> absmaxBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> deqFrontBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> deqBackBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> swBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sigBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> qsBuf_;

    // Local tensors
    AscendC::LocalTensor<int32_t> xInLocal_;
    AscendC::LocalTensor<float> wsInLocal_;
};

