122	    __aicore__ inline void Process()
123	    {
124	        if ASCEND_IS_AIV {
125	            int32_t coreIdx = AscendC::GetBlockIdx() / vecNum_;
126	            int32_t subBlockIdx = AscendC::GetSubBlockIdx();
127	            int32_t subBlockRows = blockM_ / vecNum_;
128	            int32_t mNum = CeilDiv(M_, blockM_);
129	
130	            for (int32_t localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
131	                int32_t bx = coreIdx * tasksPerCore_ + localIdx;
132	                if (bx >= mNum) { continue; }
133	
134	                for (int32_t row = 0; row < subBlockRows; ++row) {
135	                    int32_t rowIdx = bx * blockM_ + subBlockIdx * subBlockRows + row;
136	                    if (rowIdx >= M_) { continue; }
137	                    ProcessRow(rowIdx);
138	                }
139	            }
140	        }
141	    }
