144	    // -----------------------------------------------------------------------
145	    // Buffer initialization
146	    // -----------------------------------------------------------------------
147	    __aicore__ inline void InitBuffers()
148	    {
149	        // Reduce temp for absmax (2x element count)
150	        pipe_.InitBuffer(reduceTmp_, TILE_H * sizeof(float));
151	        // Absmax scalar
152	        pipe_.InitBuffer(absmaxBuf_, sizeof(float));
153	        // Input queues (1 tile = TILE_H elements of int32 or float32)
154	        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, TILE_H * sizeof(int32_t));
155	        pipe_.InitBuffer(wsInQueue_, BUFFER_NUM, TILE_H * sizeof(float));
156	        // Dequant buffers (fp32)
157	        pipe_.InitBuffer(deqFrontBuf_, TILE_H * sizeof(float));
158	        pipe_.InitBuffer(deqBackBuf_, TILE_H * sizeof(float));
159	        // SwiGLU intermediate
160	        pipe_.InitBuffer(swBuf_, TILE_H * sizeof(float));
161	        pipe_.InitBuffer(sigBuf_, TILE_H * sizeof(float));
162	        pipe_.InitBuffer(tmpBuf_, TILE_H * sizeof(float));
163	        // Quant scale tile
164	        pipe_.InitBuffer(qsBuf_, TILE_H * sizeof(float));
165	    }
166	
167	    // -----------------------------------------------------------------------
168	    // Per-row processing (two-pass)
169	    // -----------------------------------------------------------------------
170	    __aicore__ inline void ProcessRow(int32_t rowIdx)
171	    {
172	        // Load activation_scale for this row from GM to UB
173	        AscendC::LocalTensor<float> asTmp = absmaxBuf_.Get<float>();
174	        {
175	            AscendC::DataCopyExtParams copyParams{1, sizeof(float), 0, 0, 0};
176	            AscendC::DataCopyPadExtParams<float> padParams{false, 0, 0, 0.0f};
177	            AscendC::DataCopyPad(asTmp, asGM_[static_cast<uint64_t>(rowIdx)],
178	                                 copyParams, padParams);
179	        }
180	        AscendC::PipeBarrier<PIPE_MTE2>();
181	        AscendC::PipeBarrier<PIPE_ALL>();
182	        float asVal = asTmp.GetValue(0);
183	
184	        // === Pass 1: compute absmax ===
185	        float absmax = ComputeAbsmax(rowIdx, asVal);
186	
187	        // === Compute safe scale ===
188	        float scale = absmax * inv127_;
189	        float safeScale = (scale > 0.0f) ? scale : 1.0f;
190	        float invScale = 1.0f / safeScale;
191	        rsGM_.SetValue(rowIdx, safeScale);
192	
193	        // === Pass 2: compute + quantize ===
194	        ComputeAndQuantize(rowIdx, asVal, invScale);
195	    }
196	
197	    __aicore__ inline float ComputeAbsmax(int32_t rowIdx, float asVal)
198	    {
199	        float absmax = 0.0f;
200	        int32_t hTiles = CeilDiv(H_, TILE_H);
201	
202	        for (int32_t ht = 0; ht < hTiles; ++ht) {
203	            int32_t outStart = ht * TILE_H;
204	            int32_t curOut = (outStart + TILE_H <= H_) ? TILE_H : (H_ - outStart);
205	
206	            // Compute SwiGLU for this tile
207	            ComputeSwigluTile(rowIdx, outStart, curOut, asVal);
208	
209	            // Apply smooth quant: sw * quant_scale
210	            AscendC::LocalTensor<float> swLocal = swBuf_.Get<float>();
211	            AscendC::LocalTensor<float> qsLocal = qsBuf_.Get<float>();
212	            LoadGmToUbPad(qsLocal, qsGM_[static_cast<uint64_t>(outStart)],
213	                          static_cast<uint32_t>(curOut));
214	            AscendC::PipeBarrier<PIPE_MTE2>();
215	            AscendC::PipeBarrier<PIPE_ALL>();
216	            AscendC::Mul(swLocal, swLocal, qsLocal, curOut);
217	            AscendC::PipeBarrier<PIPE_V>();
218	
219	            // absmax for this tile
220	            AscendC::LocalTensor<float> absTile = tmpBuf_.Get<float>();
221	            AscendC::Abs(absTile, swLocal, curOut);
222	            AscendC::PipeBarrier<PIPE_V>();
223	
224	            AscendC::LocalTensor<float> reduceLocal = reduceTmp_.Get<float>();
225	            AscendC::LocalTensor<float> absmaxLocal = absmaxBuf_.Get<float>();
226	            AscendC::ReduceMax<float>(absmaxLocal, absTile, reduceLocal, curOut);
227	            AscendC::PipeBarrier<PIPE_ALL>();
228	
229	            float tileMax = absmaxLocal.GetValue(0);
230	            if (tileMax > absmax) {
231	                absmax = tileMax;
232	            }
233	        }
234	
235	        return absmax;
236	    }
237	
238	    __aicore__ inline void ComputeAndQuantize(
239	        int32_t rowIdx, float asVal, float invScale)
240	    {
241	        int32_t hTiles = CeilDiv(H_, TILE_H);
242	
243	        for (int32_t ht = 0; ht < hTiles; ++ht) {
244	            int32_t outStart = ht * TILE_H;
245	            int32_t curOut = (outStart + TILE_H <= H_) ? TILE_H : (H_ - outStart);
246	
247	            // Recompute SwiGLU for this tile
248	            ComputeSwigluTile(rowIdx, outStart, curOut, asVal);
249	
250	            // Smooth quant
251	            AscendC::LocalTensor<float> swLocal = swBuf_.Get<float>();
252	            AscendC::LocalTensor<float> qsLocal = qsBuf_.Get<float>();
253	            LoadGmToUbPad(qsLocal, qsGM_[static_cast<uint64_t>(outStart)],
254	                          static_cast<uint32_t>(curOut));
255	            AscendC::PipeBarrier<PIPE_MTE2>();
256	            AscendC::PipeBarrier<PIPE_ALL>();
257	            AscendC::Mul(swLocal, swLocal, qsLocal, curOut);
258	            AscendC::PipeBarrier<PIPE_V>();
259	
260	            // Quantize: * invScale
261	            AscendC::Muls(swLocal, swLocal, invScale, curOut);
262	            AscendC::PipeBarrier<PIPE_V>();
263	
264	            // Round to nearest integer
265	            AscendC::Cast(swLocal, swLocal, AscendC::RoundMode::CAST_ROUND, curOut);
266	            AscendC::PipeBarrier<PIPE_V>();
267	
268	            // Clamp to [-128, 127]
269	            AscendC::LocalTensor<float> clampLocal = deqFrontBuf_.Get<float>();
270	            AscendC::Mins(clampLocal, swLocal, 127.0f, curOut);
271	            AscendC::PipeBarrier<PIPE_V>();
272	            AscendC::Maxs(clampLocal, clampLocal, -128.0f, curOut);
273	            AscendC::PipeBarrier<PIPE_V>();
274	
275	            // Cast to int8 (same underlying bytes, reinterpret)
276	            AscendC::Cast(clampLocal, clampLocal, AscendC::RoundMode::CAST_NONE, curOut);
277	            AscendC::PipeBarrier<PIPE_V>();
278	            AscendC::LocalTensor<int8_t> i8Local =
279	                clampLocal.template ReinterpretCast<int8_t>();
280	
281	            // Write to GM
282	            auto yDst = yGM_[static_cast<uint64_t>(rowIdx) * H_ + outStart];
283	            StoreUbToGmPad(yDst,
284	                           i8Local, static_cast<uint32_t>(curOut));

