// AscendC DequantSwigluQuant kernel — fused dequant(int32->fp32) + SwiGLU + per-row int8 quant
// Single-pass: compute swiglu, smooth quant, accumulate to UB smoothBuf, track absmax.
// After all tiles: compute scale, iterate smoothBuf to quantize and write output.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_H = 512;

// ===========================================================================
// Inline helpers
// ===========================================================================

__aicore__ inline int32_t CeilDiv(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUbPad(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGmPad(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline void LoadGmToUbStridedE2(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    // Load every 2nd element starting from src
    AscendC::DataCopyExtParams copyParams{
        static_cast<uint16_t>(count),
        static_cast<uint16_t>(sizeof(T)),
        static_cast<uint16_t>(2 * sizeof(T)),
        static_cast<uint16_t>(sizeof(T)),
        0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

// ===========================================================================
// Kernel class
// ===========================================================================

class DequantSwigluQuantKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR weightScale, GM_ADDR activationScale,
        GM_ADDR quantScale, GM_ADDR y, GM_ADDR rowScale,
        int32_t M, int32_t N, int32_t H,
        int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
        int64_t swigluMode, int64_t activateLeft,
        float clampLimit, float gluAlpha, float gluBeta)
    {
        this->M_ = M;
        this->N_ = N;
        this->H_ = H;
        this->blockM_ = blockM;
        this->usedCoreNum_ = usedCoreNum;
        this->tasksPerCore_ = tasksPerCore;
        this->swigluMode_ = static_cast<int32_t>(swigluMode);
        this->activateLeft_ = static_cast<int32_t>(activateLeft);
        this->clampLimit_ = clampLimit;
        this->gluAlpha_ = gluAlpha;
        this->gluBeta_ = gluBeta;
        this->inv127_ = 1.0f / 127.0f;
        this->vecNum_ = AscendC::GetSubBlockNum();

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(x),
                             static_cast<uint64_t>(M) * N);
        wsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(weightScale),
                              static_cast<uint64_t>(1) * N);
        asGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(activationScale),
                              static_cast<uint64_t>(M) * 1);
        qsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(quantScale),
                              static_cast<uint64_t>(1) * H);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y),
                             static_cast<uint64_t>(M) * H);
        rsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(rowScale),
                              static_cast<uint64_t>(M));

        if ASCEND_IS_AIV {
            InitBuffers();
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx() / vecNum_;
            int32_t subBlockIdx = AscendC::GetSubBlockIdx();
            int32_t subBlockRows = blockM_ / vecNum_;
            int32_t mNum = CeilDiv(M_, blockM_);

            for (int32_t localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                int32_t bx = coreIdx * tasksPerCore_ + localIdx;
                if (bx >= mNum) { continue; }

                for (int32_t row = 0; row < subBlockRows; ++row) {
                    int32_t rowIdx = bx * blockM_ + subBlockIdx * subBlockRows + row;
                    if (rowIdx >= M_) { continue; }
                    ProcessRow(rowIdx);
                }
            }
        }
    }

private:
    __aicore__ inline void InitBuffers()
    {
        pipe_.InitBuffer(reduceTmp_, TILE_H * sizeof(float));
        pipe_.InitBuffer(scalarBuf_, sizeof(float));
        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, TILE_H * sizeof(int32_t));
        pipe_.InitBuffer(wsInQueue_, BUFFER_NUM, TILE_H * sizeof(float));
        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, TILE_H * sizeof(int8_t));
        pipe_.InitBuffer(dqFront_, TILE_H * sizeof(float));
        pipe_.InitBuffer(dqBack_, TILE_H * sizeof(float));
        pipe_.InitBuffer(swBuf_, TILE_H * sizeof(float));
        pipe_.InitBuffer(sigBuf_, TILE_H * sizeof(float));
        pipe_.InitBuffer(tmpBuf_, TILE_H * sizeof(float));
        pipe_.InitBuffer(qsBuf_, TILE_H * sizeof(float));
    }

    // -----------------------------------------------------------------------
    // Per-row processing — single pass
    // -----------------------------------------------------------------------
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        // Load activation_scale for this row
        AscendC::LocalTensor<float> sBuf = scalarBuf_.Get<float>();
        {
            AscendC::DataCopyExtParams cp{1, sizeof(float), 0, 0, 0};
            AscendC::DataCopyPadExtParams<float> pp{false, 0, 0, 0.0f};
            AscendC::DataCopyPad(sBuf, asGM_[static_cast<uint64_t>(rowIdx)], cp, pp);
        }
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        float asVal = sBuf.GetValue(0);

        float absmax = 0.0f;
        int32_t hTiles = CeilDiv(H_, TILE_H);

        // --- Compute + accumulate smooth quant, track absmax ---
        for (int32_t ht = 0; ht < hTiles; ++ht) {
            int32_t outStart = ht * TILE_H;
            int32_t curOut = (outStart + TILE_H <= H_) ? TILE_H : (H_ - outStart);

            // Compute SwiGLU
            ComputeSwiGLU(rowIdx, outStart, curOut, asVal);

            // Smooth quant: sw * quant_scale
            AscendC::LocalTensor<float> sw = swBuf_.Get<float>();
            AscendC::LocalTensor<float> qs = qsBuf_.Get<float>();
            LoadGmToUbPad(qs, qsGM_[static_cast<uint64_t>(outStart)],
                          static_cast<uint32_t>(curOut));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            AscendC::Mul(sw, sw, qs, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Track absmax
            AscendC::LocalTensor<float> absTile = tmpBuf_.Get<float>();
            AscendC::Abs(absTile, sw, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::LocalTensor<float> redBuf = reduceTmp_.Get<float>();
            AscendC::LocalTensor<float> amBuf = scalarBuf_.Get<float>();
            AscendC::ReduceMax<float>(amBuf, absTile, redBuf, curOut);
            AscendC::PipeBarrier<PIPE_ALL>();
            float tm = amBuf.GetValue(0);
            if (tm > absmax) { absmax = tm; }

            // --- Quantize and write this tile to output ---
            // Step 1: compute scale from absmax-on-the-fly
            float curScale = absmax * inv127_;
            float curSafeScale = (curScale > 0.0f) ? curScale : 1.0f;

            // Write rowScale (will be overwritten as absmax grows, final value is correct after last tile)
            AscendC::LocalTensor<float> rsUb = sBuf;
            rsUb.SetValue(0, curSafeScale);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::GlobalTensor<float> rsDst = rsGM_[static_cast<uint64_t>(rowIdx)];
            AscendC::DataCopyExtParams rsCp{1, sizeof(float), 0, 0, 0};
            AscendC::DataCopyPad(rsDst, rsUb, rsCp);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();

            // Step 2: re-read sw, re-apply smooth quant, and quantize
            // Recompute swiglu for quantization
            ComputeSwiGLU(rowIdx, outStart, curOut, asVal);

            // Re-load qs and smooth quant
            AscendC::LocalTensor<float> sw2 = swBuf_.Get<float>();
            AscendC::LocalTensor<float> qs2 = qsBuf_.Get<float>();
            LoadGmToUbPad(qs2, qsGM_[static_cast<uint64_t>(outStart)],
                          static_cast<uint32_t>(curOut));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            AscendC::Mul(sw2, sw2, qs2, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            float invScale = 1.0f / curSafeScale;

            // Multiply by invScale
            AscendC::Muls(sw2, sw2, invScale, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Round to nearest integer
            AscendC::Cast(sw2, sw2, AscendC::RoundMode::CAST_ROUND, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Clamp to [-128, 127]
            AscendC::LocalTensor<float> cl = dqFront_.Get<float>();
            AscendC::Mins(cl, sw2, 127.0f, curOut);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Maxs(cl, cl, -128.0f, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            // Cast float→half→int8
            AscendC::LocalTensor<half> hTmp = dqBack_.Get<half>();
            AscendC::Cast(hTmp, cl, AscendC::RoundMode::CAST_NONE, curOut);
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::LocalTensor<int8_t> yOut = yOutQueue_.AllocTensor<int8_t>();
            AscendC::Cast(yOut, hTmp, AscendC::RoundMode::CAST_ROUND, curOut);
            AscendC::PipeBarrier<PIPE_V>();
            yOutQueue_.EnQue(yOut);

            yOut = yOutQueue_.DeQue<int8_t>();
            AscendC::GlobalTensor<int8_t> yDst =
                yGM_[static_cast<uint64_t>(rowIdx) * H_ + outStart];
            StoreUbToGmPad(yDst, yOut, static_cast<uint32_t>(curOut));
            yOutQueue_.FreeTensor(yOut);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
        }
    }

    // -----------------------------------------------------------------------
    // Compute SwiGLU for one tile (result in swBuf_)
    // -----------------------------------------------------------------------
    __aicore__ inline void ComputeSwiGLU(
        int32_t rowIdx, int32_t outStart, int32_t curOut, float asVal)
    {
        if (swigluMode_ == 0) {
            ComputeMode0(rowIdx, outStart, curOut, asVal);
        } else {
            ComputeMode1(rowIdx, outStart, curOut, asVal);
        }
    }

    __aicore__ inline void ComputeMode0(
        int32_t rowIdx, int32_t outStart, int32_t curOut, float asVal)
    {
        // Load + dequant front
        AscendC::LocalTensor<int32_t> xIn = xInQueue_.AllocTensor<int32_t>();
        LoadGmToUbPad(xIn, xGM_[static_cast<uint64_t>(rowIdx) * N_ + outStart],
                      static_cast<uint32_t>(curOut));
        xInQueue_.EnQue(xIn);
        xIn = xInQueue_.DeQue<int32_t>();

        AscendC::LocalTensor<float> wsIn = wsInQueue_.AllocTensor<float>();
        LoadGmToUbPad(wsIn, wsGM_[static_cast<uint64_t>(outStart)],
                      static_cast<uint32_t>(curOut));
        wsInQueue_.EnQue(wsIn);
        wsIn = wsInQueue_.DeQue<float>();

        AscendC::LocalTensor<float> front = dqFront_.Get<float>();
        AscendC::Cast(front, xIn, AscendC::RoundMode::CAST_NONE, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(front, front, wsIn, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(front, front, asVal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        wsInQueue_.FreeTensor(wsIn);
        xInQueue_.FreeTensor(xIn);

        // Load + dequant back
        xIn = xInQueue_.AllocTensor<int32_t>();
        LoadGmToUbPad(xIn,
                      xGM_[static_cast<uint64_t>(rowIdx) * N_ + H_ + outStart],
                      static_cast<uint32_t>(curOut));
        xInQueue_.EnQue(xIn);
        xIn = xInQueue_.DeQue<int32_t>();

        wsIn = wsInQueue_.AllocTensor<float>();
        LoadGmToUbPad(wsIn, wsGM_[static_cast<uint64_t>(H_ + outStart)],
                      static_cast<uint32_t>(curOut));
        wsInQueue_.EnQue(wsIn);
        wsIn = wsInQueue_.DeQue<float>();

        AscendC::LocalTensor<float> back = dqBack_.Get<float>();
        AscendC::Cast(back, xIn, AscendC::RoundMode::CAST_NONE, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(back, back, wsIn, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(back, back, asVal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        wsInQueue_.FreeTensor(wsIn);
        xInQueue_.FreeTensor(xIn);

        // SwiGLU: select glu/lin based on activateLeft
        AscendC::LocalTensor<float> gluL, linL;
        if (activateLeft_) {
            gluL = dqFront_.Get<float>(); linL = dqBack_.Get<float>();
        } else {
            gluL = dqBack_.Get<float>(); linL = dqFront_.Get<float>();
        }

        // sigmoid(glu) = 1/(1+exp(-glu))
        AscendC::LocalTensor<float> sg = sigBuf_.Get<float>();
        AscendC::Muls(sg, gluL, -1.0f, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Exp(sg, sg, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Adds(sg, sg, 1.0f, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Reciprocal(sg, sg, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // sw = lin * (glu * sigmoid)
        AscendC::LocalTensor<float> sw = swBuf_.Get<float>();
        AscendC::Mul(sw, gluL, sg, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(sw, sw, linL, curOut);
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void ComputeMode1(
        int32_t rowIdx, int32_t outStart, int32_t curOut, float asVal)
    {
        int32_t inStart = outStart * 2;

        // Load + dequant glu (even indices)
        AscendC::LocalTensor<int32_t> xIn = xInQueue_.AllocTensor<int32_t>();
        LoadGmToUbStridedE2(xIn, xGM_[static_cast<uint64_t>(rowIdx) * N_ + inStart],
                            static_cast<uint32_t>(curOut));
        xInQueue_.EnQue(xIn);
        xIn = xInQueue_.DeQue<int32_t>();

        AscendC::LocalTensor<float> wsIn = wsInQueue_.AllocTensor<float>();
        LoadGmToUbStridedE2(wsIn, wsGM_[static_cast<uint64_t>(inStart)],
                            static_cast<uint32_t>(curOut));
        wsInQueue_.EnQue(wsIn);
        wsIn = wsInQueue_.DeQue<float>();

        AscendC::LocalTensor<float> glu = dqFront_.Get<float>();
        AscendC::Cast(glu, xIn, AscendC::RoundMode::CAST_NONE, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(glu, glu, wsIn, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(glu, glu, asVal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        wsInQueue_.FreeTensor(wsIn);
        xInQueue_.FreeTensor(xIn);

        // Load + dequant lin (odd indices)
        xIn = xInQueue_.AllocTensor<int32_t>();
        LoadGmToUbStridedE2(xIn,
                            xGM_[static_cast<uint64_t>(rowIdx) * N_ + inStart + 1],
                            static_cast<uint32_t>(curOut));
        xInQueue_.EnQue(xIn);
        xIn = xInQueue_.DeQue<int32_t>();

        wsIn = wsInQueue_.AllocTensor<float>();
        LoadGmToUbStridedE2(wsIn, wsGM_[static_cast<uint64_t>(inStart + 1)],
                            static_cast<uint32_t>(curOut));
        wsInQueue_.EnQue(wsIn);
        wsIn = wsInQueue_.DeQue<float>();

        AscendC::LocalTensor<float> lin = dqBack_.Get<float>();
        AscendC::Cast(lin, xIn, AscendC::RoundMode::CAST_NONE, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(lin, lin, wsIn, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(lin, lin, asVal, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        wsInQueue_.FreeTensor(wsIn);
        xInQueue_.FreeTensor(xIn);

        // Mode 1: glu_c = min(glu, L), lin_c = clamp(lin, -L, L)
        AscendC::LocalTensor<float> gluC = tmpBuf_.Get<float>();
        AscendC::Mins(gluC, glu, clampLimit_, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        AscendC::Mins(lin, lin, clampLimit_, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Maxs(lin, lin, -clampLimit_, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // sigmoid(alpha * glu_c)
        AscendC::LocalTensor<float> sg = sigBuf_.Get<float>();
        AscendC::Muls(sg, gluC, gluAlpha_, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(sg, sg, -1.0f, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Exp(sg, sg, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Adds(sg, sg, 1.0f, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Reciprocal(sg, sg, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // lin_c + beta
        AscendC::Adds(lin, lin, gluBeta_, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        // sw = glu_c * sigmoid * (lin_c + beta)
        AscendC::LocalTensor<float> sw = swBuf_.Get<float>();
        AscendC::Mul(sw, gluC, sg, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(sw, sw, lin, curOut);
        AscendC::PipeBarrier<PIPE_V>();
    }

private:
